import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../../app/providers.dart';
import '../../../../core/theme/app_colors.dart';
class GoalsJarsScreen extends ConsumerStatefulWidget{const GoalsJarsScreen({super.key});@override ConsumerState<GoalsJarsScreen> createState()=>_S();}
class _S extends ConsumerState<GoalsJarsScreen> with SingleTickerProviderStateMixin{late final TabController tabs;bool loading=true;List<Map<String,dynamic>>goals=[],bucket=[],jars=[];@override void initState(){super.initState();tabs=TabController(length:3,vsync:this);_load();}@override void dispose(){tabs.dispose();super.dispose();}Future<void>_load()async{setState(()=>loading=true);try{final r=ref.read(coupleLifeRepositoryProvider);final x=await Future.wait([r.goals(),r.bucketItems(),r.jars()]);goals=x[0];bucket=x[1];jars=x[2];}finally{if(mounted)setState(()=>loading=false);}}Future<String?>_ask(String title,{String hint='Write something meaningful…'})async{final c=TextEditingController();return showDialog<String>(context:context,builder:(x)=>AlertDialog(title:Text(title),content:TextField(controller:c,autofocus:true,decoration:InputDecoration(hintText:hint)),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,c.text.trim()),child:const Text('Save'))]));}Future<void>_add()async{final r=ref.read(coupleLifeRepositoryProvider);if(tabs.index==0){final t=await _ask('New shared goal');if(t?.isNotEmpty==true)await r.createGoal(t!);}else if(tabs.index==1){final t=await _ask('Add to our bucket list');if(t?.isNotEmpty==true)await r.createBucketItem(t!);}else{final t=await _ask('Create a couple jar');if(t?.isNotEmpty==true){final type=await showDialog<String>(context:context,builder:(c)=>SimpleDialog(title:const Text('Jar style'),children:['appreciation','love','funny','dreams','date_ideas','surprise'].map((x)=>SimpleDialogOption(onPressed:()=>Navigator.pop(c,x),child:Text(x.replaceAll('_',' ')))).toList()));if(type!=null)await r.createJar(t!,type);}}_load();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Dreams & Goals'),bottom:TabBar(controller:tabs,tabs:const[Tab(text:'Goals'),Tab(text:'Bucket'),Tab(text:'Jars')])),body:loading?const Center(child:CircularProgressIndicator()):TabBarView(controller:tabs,children:[_goals(),_bucket(),_jars()]),floatingActionButton:FloatingActionButton(onPressed:_add,child:const Icon(Icons.add)));
Widget _goals()=>ListView(padding:const EdgeInsets.all(18),children:goals.isEmpty?[const _Empty('No shared goals yet ♡')]:goals.map((g)=>Card(child:ListTile(onTap:()=>_goal(g),leading:const CircleAvatar(child:Icon(Icons.flag_outlined)),title:Text('${g['title']??'Shared goal'}'),subtitle:Text('${g['type']??'shared'} • ${g['status']??'active'}'),trailing:const Icon(Icons.chevron_right)))).toList());Future<void>_goal(Map<String,dynamic>g)async{final id='${g['id']}';final v=await _ask('Add progress',hint:'Progress number, e.g. 25');if(v==null)return;final n=double.tryParse(v);if(n==null)return;await ref.read(coupleLifeRepositoryProvider).addGoalProgress(id,n,note:'Progress update');final comment=await _ask('Encouragement',hint:'Optional note for your partner');if(comment?.isNotEmpty==true)await ref.read(coupleLifeRepositoryProvider).addGoalComment(id,comment!);_load();}
Widget _bucket()=>ListView(padding:const EdgeInsets.all(18),children:bucket.isEmpty?[const _Empty('Your bucket list is waiting for the first dream ♡')]:bucket.map((b)=>Card(child:Padding(padding:const EdgeInsets.all(8),child:ListTile(leading:const CircleAvatar(child:Icon(Icons.auto_awesome)),title:Text('${b['title']??'Bucket idea'}'),subtitle:Text('${b['status']??'active'}'),trailing:PopupMenuButton<String>(onSelected:(v)async{final r=ref.read(coupleLifeRepositoryProvider);if(v=='complete')await r.completeBucketItem('${b['id']}');if(v=='milestone')await r.convertBucketToMilestone('${b['id']}');if(v=='comment'){final x=await _ask('Encourage this dream');if(x?.isNotEmpty==true)await r.addBucketComment('${b['id']}',x!);}await _load();},itemBuilder:(_)=>const[PopupMenuItem(value:'comment',child:Text('Comment')),PopupMenuItem(value:'complete',child:Text('Mark complete')),PopupMenuItem(value:'milestone',child:Text('Convert to Milestone'))]))))).toList());
Widget _jars()=>ListView(padding:const EdgeInsets.all(18),children:jars.isEmpty?[const _Empty('Create a jar for little things worth keeping ♡')]:jars.map((j)=>Card(child:ListTile(onTap:()=>_jar(j),leading:const CircleAvatar(backgroundColor:AppColors.blush,child:Icon(Icons.inventory_2_outlined,color:AppColors.rose)),title:Text('${j['title']??'Our Jar'}'),subtitle:Text('${j['type']??'love'}'.replaceAll('_',' ')),trailing:const Icon(Icons.chevron_right)))).toList());Future<void>_jar(Map<String,dynamic>j)async{final id='${j['id']}';final entries=await ref.read(coupleLifeRepositoryProvider).jarEntries(id);if(!mounted)return;await showModalBottomSheet(context:context,isScrollControlled:true,builder:(c)=>Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,children:[Text('${j['title']??'Our Jar'}',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:8),if(entries.isEmpty)const Text('Nothing inside yet.')else SizedBox(height:220,child:ListView(children:entries.map((e)=>ListTile(leading:const Icon(Icons.favorite_outline,color:AppColors.rose),title:Text('${e['body']??''}'))).toList())),const SizedBox(height:8),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()async{final x=await _ask('Add to jar');if(x?.isNotEmpty==true){await ref.read(coupleLifeRepositoryProvider).addJarEntry(id,x!);if(c.mounted)Navigator.pop(c);_jar(j);}},icon:const Icon(Icons.add),label:const Text('Add note'))),const SizedBox(width:8),Expanded(child:FilledButton.icon(onPressed:()async{final p=await ref.read(coupleLifeRepositoryProvider).randomJarPick(id);if(c.mounted)showDialog(context:c,builder:(d)=>AlertDialog(title:const Text('A little pick for you ✨'),content:Text('${p['body']??'Add a few notes first.'}'),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Keep it'))]));},icon:const Icon(Icons.casino_outlined),label:const Text('Shake')))]),const SizedBox(height:20)])));}}
class _Empty extends StatelessWidget{const _Empty(this.text);final String text;@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.only(top:100),child:Center(child:Text(text,textAlign:TextAlign.center,style:const TextStyle(color:AppColors.muted))));}
